import json
with open('baseline-packages.json') as f: before = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_packages(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg.get('resolvedVersion', pkg.get('requestedVersion',''))
        result[name] = pkgs
    return result

b = get_packages(before)
a = get_packages(after)
changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for pkg in sorted(set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys()))):
        bv = b.get(proj,{}).get(pkg,'(none)')
        av = a.get(proj,{}).get(pkg,'(none)')
        if bv != av:
            changes.append(f'  {proj}: {pkg} {bv} -> {av}')
if changes:
    print('Version changes:')
    for c in changes: print(c)
else:
    print('No version changes (fully version-neutral)')
"

